SET LOCAL lock_timeout = '5s';
DO $q$
BEGIN
    IF to_regclass('nexus.aspect_extraction_queue') IS NOT NULL THEN
        ALTER TABLE nexus.aspect_extraction_queue ADD COLUMN IF NOT EXISTS collection_id bigint;
        IF NOT EXISTS (SELECT 1 FROM pg_constraint
                        WHERE conrelid = 'nexus.aspect_extraction_queue'::regclass AND conname = 'aspect_extraction_queue_collection_id_check') THEN
            ALTER TABLE nexus.aspect_extraction_queue
            ADD CONSTRAINT aspect_extraction_queue_collection_id_check CHECK ((NULLIF(collection, '') IS NULL) = (collection_id IS NULL)) NOT VALID;
        END IF;
    END IF;
END
$q$;

rollback.sql:
DO $q$
BEGIN
    IF to_regclass('nexus.aspect_extraction_queue') IS NOT NULL THEN
        ALTER TABLE nexus.aspect_extraction_queue DROP CONSTRAINT IF EXISTS aspect_extraction_queue_collection_id_check;
    END IF;
END
$q$;

changeSet.sql:
ALTER TABLE nexus.catalog_collections ADD CONSTRAINT catalog_collections_superseded_by_id_check CHECK ((superseded_by = '') = (superseded_by_id IS NULL)) NOT VALID;
DO $v$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM nexus.catalog_collections c WHERE (c.superseded_by = '') <> (c.superseded_by_id IS NULL)) THEN
        BEGIN
            ALTER TABLE nexus.catalog_collections VALIDATE CONSTRAINT catalog_collections_superseded_by_id_check;
        EXCEPTION WHEN check_violation THEN
            NULL;   -- a row the guard could not see violates it (RLS-blind posture): leave the CHECK NOT VALID for the stamp's on_complete
        END;
    END IF;
END
$v$;
